   "id": "z16a3a210",
   "sez": "sport",
   "titolo": "Infortunio per Bagnaia nella Sprint in Qatar, Marc Marquez si aggiudica la gara",
   "orig": "Terribile incidente per Bagnaia nella Sprint in Qatar. Gara interrotta, poi vince Marc Marquez",
   "lead": "Durante la gara Sprint del Gran Premio del Qatar di MotoGP, il pilota italiano Francesco Bagnaia è stato coinvolto in un grave incidente causato da un contatto in frenata con lo spagnolo Fermín Aldeguer. La corsa è stata temporaneamente interrotta per permettere i soccorsi; Bagnaia, rimasto sempre cosciente, ha riportato la frattura di due dita del piede. Alla ripartenza della competizione, lo spagnolo Marc Marquez si è aggiudicato la vittoria precedendo Fabio Di Giannantonio e Jorge Martin, conquistando così la possibilità di chiudere la contesa mondiale.",
   "more": [
    "La gara Sprint della MotoGP è un formato introdotto per assegnare punti supplementari in classifica alla vigilia del Gran Premio principale. Le gare brevi e ad alta intensità aumentano la competitività tra i piloti, ma richiedono massima stanchezza fisica e precisione nelle staccate per evitare contatti ad alta velocità tra i gareggianti."
   ],
