   "id": "z3e2fe9c9",
   "sez": "prima",
   "titolo": "Scade lo sconto sulle accise del diesel in Italia, attesi rincari alla pompa",
   "orig": "Accise, il governo non rinnova gli sconti sul diesel: da domani prezzi in aumento",
   "lead": "In Italia scade alla mezzanotte del ventotto ottobre lo sconto fiscale sulle accise del gasolio, una misura che garantiva una riduzione di 4,88 centesimi di euro al litro sui prezzi al consumo. La mancata pubblicazione del rinnovo del provvedimento all'interno della Gazzetta Ufficiale comporta un immediato aumento del costo del carburante alla pompa a partire dalla giornata di domani. Gli operatori del settore e le associazioni dei consumatori segnalano il concreto rischio di rincari generalizzati sul prezzo del diesel a carico degli automobilisti.",
   "more": [
    "Le accise sui carburanti rappresentano una componente rilevante del prezzo finale della benzina e del gasolio in Italia. Gli interventi temporanei di riduzione delle imposte vengono adottati dai governi per mitigare l'impatto dell'inflazione sui trasporti e sulla distribuzione delle merci, ma richiedono un continuo rifinanziamento economico per rimanere in vigore."
   ],
