   "id": "z5bf2416e",
   "sez": "sport",
   "titolo": "La calciatrice libanese Celine Haidar torna sul campo da gioco come allenatrice",
   "orig": "Lebanese footballer refuses to give up after injuries from Israeli strike",
   "lead": "La calciatrice libanese Celine Haidar è tornata sui campi di gioco per svolgere il ruolo di allenatrice dopo essere sopravvissuta a un attacco aereo israeliano che l'aveva lasciata in stato di coma. Nonostante le gravi ferite riportate nell'esplosione, l'atleta ha ripreso le attività sportive guidando le sessioni di allenamento con la propria squadra. L'esperienza dell'atleta testimonia la resilienza del movimento sportivo locale di fronte al conflitto. Lo riferisce Al Jazeera.",
   "more": [
    "La continuità delle attività sportive in contesti di conflitto rappresentano un importante elemento di ripresa sociale e psicologica per le comunità colpite da violenze belliche. Il reinserimento degli atleti feriti nei ruoli tecnici e dirigenziali favorisce il supporto morale delle nuove generazioni e la crescita del settore agonistico locale."
   ],
