   "sez": "mondo",
   "titolo": "L'ANC sudaffricano registra il peggior risultato di sempre alle amministrative",
   "orig": "South Africa's ANC facing worst-ever performance in local elections",
   "lead": "Nelle elezioni amministrative in Sudafrica, l'African National Congress ha registrato la percentuale di consensi più bassa della propria storia politica secondo i risultati quasi definitivi dello spoglio. Il partito di governo sconta le forti insoddisfazioni dei cittadini legate alle carenze nella gestione dei servizi pubblici comunali, tra cui le frequenti interruzioni dell'erogazione dell'acqua e dell'energia elettrica. I dati elettorali confermano una progressiva flessione del sostegno popolare verso la formazione politica storicamente maggioritaria nel Paese. Lo riferisce Deutsche Welle.",
   "more": [
    "L'African National Congress è la forza politica principale del Sudafrica dalla fine del regime di apartheid nel 1994. Negli ultimi anni, il calo dei consensi riflette le difficoltà economiche del Paese, la disoccupazione giovanile e i problemi strutturali nella gestione delle infrastrutture pubbliche gestite dalle amministrazioni locali."
   ],
