   "id": "z942d6047",
   "sez": "spazio",
   "titolo": "La NASA apre le selezioni per la nuova classe di astronauti delle missioni lunari",
   "orig": "NASA Seeks Next Generation of Explorers to Join Astronaut Corps",
   "lead": "L'agenzia spaziale statunitense NASA ha aperto ufficialmente le candidature per la selezione della nuova classe di astronauti destinati alle future missioni di esplorazione umana. I candidati selezionati parteciperanno ai programmi per il ritorno dell'uomo sulla Luna, alla costruzione della base lunare e alla preparazione delle prime missioni con equipaggio dirette verso Marte. Nel frattempo, l'astronauta Anil Menon ha effettuato il proprio voto per le elezioni di metà mandato inviando una scheda elettronica dalla Stazione Spaziale Internazionale.",
   "more": [
    "I programmi di esplorazione umana della NASA prevedono l'addestramento intensivo di specialisti di missione per il volo spaziale di lunga durata. Il voto espresso dagli astronauti in orbita avviene attraverso procedure informatiche sicure garantite dal coordinamento tra l'agenzia spaziale e le autorità elettorali delle contee statunitensi di residenza."
   ],
