   "id": "zeb090b5b",
   "sez": "ambiente",
   "titolo": "Rio Tinto finanzia la barriera contro l'invasione dei rospi in Australia",
   "orig": "Mining giant joins fight to stop killer toad march across Australia",
   "lead": "La multinazionale mineraria Rio Tinto ha aderito al piano di finanziamento per la creazione di una zona di contenimento dei rospi delle canne in Australia, stanziando una quota di 28 milioni di dollari australiani. Il progetto punta a realizzare una barriera ecologica nella regione di Pilbara per bloccare l'avanzata della specie invasiva dannosa per la fauna locale. L'iniziativa mira a tutelare la biodiversità e gli ecosistemi indigeni dall'impatto distruttivo provocato dalla diffusione dell'anfibio. Lo riferisce BBC News.",
   "more": [
    "Il rospo delle canne è una specie aliena introdotta in Australia nel ventesimo secolo per contrastare i parassiti dell'agricoltura. La sua rapida proliferazione priva di predatori naturali ha provocato gravi danni alla fauna nativa, rendendo necessari interventi di contenimento geografico per proteggere i territori non ancora colonizzati."
   ],
