   "id": "z846fb395",
   "sez": "ingegneria",
   "titolo": "Inaugurato in Cina il Changtai Yangtze River Bridge, ponte strallato da record",
   "orig": "Il ponte strallato con la campata più lunga al mondo è il Changtai Yangtze River Bridge in Cina di 1176m",
   "lead": "Nella provincia di Jiangsu in Cina è stato inaugurato il Changtai Yangtze River Bridge, la struttura strallata con la campata principale più lunga al mondo, compresa tra i 1.176 e i 1.208 metri. L'opera rappresenta inoltre la più grande struttura combinata autostradale e ferroviaria dotata di travata a traliccio in acciaio mai realizzata nell'ingegneria delle grandi infrastrutture. Il ponte fissa nuovi primati mondiali per la tecnica costruttiva e la capacità di integrazione del traffico su gomma e su rotaia. Lo riferisce Geopop.",
   "more": [
    "I ponti strallati utilizzano cavi d'acciaio ancorati a torri di sostegno per sorreggere l'impalcato stradale e ferroviario. La costruzione di campate di grande luce su corsi d'acqua di notevole ampiezza richiede calcoli complessi per garantire la stabilità aerodinamica e la resistenza ai carichi pesanti e agli eventi sismici."
   ],
