   "id": "zbcf87f9e",
   "sez": "ambiente",
   "titolo": "La plastica accumulata nel Pacifico altera la colorazione dell'oceano",
   "orig": "The Great Pacific Garbage Patch may now have so much plastic, it’s changing ocean's colour",
   "lead": "La grande chiazza di rifiuti di plastica accumulata nell'Oceano Pacifico ha raggiunto dimensioni e densità tali da alterare la tonalità di colore delle acque marine circostanti, secondo le rilevazioni effettuate da un gruppo di scienziati. L'elevata concentrazione di frammenti plastici nelle correnti oceaniche causa un netto schiarimento del mare, che appare visibilmente più blu e verde. L'accumulo dei materiali sintetici dimostra l'impatto dell'inquinamento da plastica sugli ecosistemi acquatici del pianeta. Lo riferisce RNZ.",
   "more": [
    "Il Great Pacific Garbage Patch è una vasta area di accumulo di detriti plastici formata dalle correnti circolari dell'Oceano Pacifico. La frammentazione della plastica in microplastiche causa la dispersione di particelle che riflettono la luce solare, modificando la trasparenza dell'acqua e minacciando direttamente le specie marine che la ingeriscono."
   ],
   "fonti": [
    {
     "n": "RNZ",
     "p": "XX",
     "c": "Wellington",
     "u": "https://www.rnz.co.nz/news/world/2423812/the-great-pacific-garbage-patch-may-now-have-so-much-plastic-it-s-changing-ocean-s-colour",
     "angolo": "",
     "atlas": "New Zealand",
     "t": "2026-11-08T06:14+13:00"
    }
   ],
