   "titolo": "SABO Project reinterpreta la suddivisione degli spazi in un appartamento a Manhattan",
   "orig": "SABO Project \"softens divisions\" inside Manhattan apartment",
   "lead": "Lo studio di progettazione SABO Project, con sedi a New York e Parigi, ha completato l'intervento di ristrutturazione di un appartamento di dimensioni ridotte situato nel quartiere Lower East Side a Manhattan. L'opera si caratterizza per l'introduzione di pareti divisorie dalle forme arrotondate e per l'impiego di accesi dettagli di colore verde destinati ad ammorbidire le separazioni spaziali interne. La soluzione architettonica intende ottimizzare la vivibilità e l'organizzazione degli ambienti domestici contenuti. Lo riferisce Dezeen.",
   "more": [
    "L'architettura d'interni negli appartamenti metropolitani punta sulla flessibilità degli spazi e sull'uso di pareti divisorie non convenzionali per migliorare la luminosità. L'integrazione di elementi curvi e di cromie vivaci consente di definire le diverse funzioni abitative senza ricorrere a murature tradizionali."
   ],
