   "titolo": "Regole per l'impiego dei docenti di sostegno nelle supplenze scolastiche",
   "orig": "Docente di sostegno può essere usato per supplenze? E se lo studente è assente? Il Punto di De Martino",
   "lead": "La gestione del personale docente di sostegno nell'ambito della scuola italiana suscita interrogativi in merito all'impiego dei docenti specializzati per la sostituzione temporanea dei colleghi assenti. Gli aspetti normativi disciplinano i casi in cui l'insegnante possa essere assegnato a supplenze in altre classi sia durante la presenza in aula dell'alunno con disabilità, sia durante la sua assenza da scuola. Le norme precisano i vincoli e le priorità per la tutela della continuità didattica integrativa. Lo riferisce Orizzonte Scuola.",
   "more": [
    "Il docente di sostegno è una figura specializzata assegnata alle classi per favorire l'integrazione degli studenti con disabilità o con bisogni educativi speciali. Le direttive ministeriali regolano le funzioni dell'insegnante per garantire la priorità dell'assistenza didattica individualizzata rispetto alle esigenze organizzative dell'istituto scolastico."
   ],
