   "sez": "mondo",
   "titolo": "Lettera al Sud Sudan: la violenza è storia, non natura",
   "orig": "Letter| Violence is our history, not our nature",
   "lead": "Un cittadino sud sudanese ha indirizzato ai propri connazionali una serie di sette lettere, di cui questa rappresenta la terza, per riflettere sulla storia del Paese. Nel messaggio si sostiene che la violenza, pur avendo segnato profondamente la storia del Sud Sudan a partire dal 1955, non debba essere considerata una caratteristica intrinseca della natura umana della popolazione. L'obiettivo dell'autore è promuovere una consapevolezza diversa tra i cittadini, separando il passato bellico dall'identità nazionale futura. Lo riferisce Radio Tamazuj.",
