   "id": "z667c3514",
   "sez": "dibattito",
   "titolo": "Norvegia, la leader conservatrice Søreide contestata per i prezzi del diesel",
   "orig": "Søreide møtt med kraftig diesel-kritikk i nord: – Folk melder seg ut i protest",
   "lead": "In Norvegia, la leader del partito conservatore Høyre, Ine Eriksen Søreide, è stata duramente contestata dai membri del proprio partito nelle regioni settentrionali a causa del caro carburante. I manifestanti e i delegati locali lamentano l'assenza di promesse concrete sulla riduzione dei prezzi del diesel, arrivando a minacciare l'uscita dal partito in segno di protesta. Søreide ha risposto definendo le critiche prevedibili, ma ha confermato di non poter fornire garanzie immediate sui costi del rifornimento per i residenti del nord. Lo riferisce NRK.",
   "more": [
    "Il dibattito sui costi del carburante in Norvegia è acceso nelle zone settentrionali, dove le grandi distanze rendono i cittadini dipendenti dai veicoli privati. Nonostante la Norvegia sia un importante produttore di petrolio, i prezzi alla pompa sono influenzati dalle tasse ambientali e dalle fluttuazioni del mercato globale, alimentando tensioni tra transizione ecologica e potere d'acquisto."
   ],
