   "titolo": "Matrimonio di massa a Gaza: 250 coppie spose tra le macerie",
   "orig": "Gaza wedding festival sees 250 couples married at the same time",
   "lead": "Un festival di nozze collettive ha celebrato il matrimonio di 250 coppie di sposi palestinesi tra le strade della Striscia di Gaza, ancora segnate dalle macerie dei recenti conflitti. L'evento di massa è stato organizzato per permettere a numerosi giovani di unirsi in matrimonio nonostante le difficili condizioni economiche e sociali causate dalle ostilità. La celebrazione ha trasformato temporaneamente il paesaggio urbano distrutto in un luogo di festa comunitaria, rappresentando un momento di condivisione e speranza per la popolazione locale colpita dalla crisi umanitaria. Lo riferisce BBC News.",
   "more": [
    "I matrimoni collettivi sono eventi comuni in contesti di crisi economica o bellica, spesso sostenuti da organizzazioni benefiche per ridurre i costi elevati delle singole cerimonie. Nella Striscia di Gaza, tali iniziative servono anche a rafforzare il tessuto sociale e a mantenere le tradizioni culturali nonostante le distruzioni materiali."
   ],
