   "id": "z762610cd",
   "sez": "mondo",
   "titolo": "Mississippi, Scott Colom verso un'elezione storica al Senato",
   "orig": "Scott Colom and Black Mississippians stand on the cusp of Senate history as vote count stretches on",
   "lead": "Nello stato del Mississippi, negli Stati Uniti, il conteggio dei voti sta tenendo la popolazione con il fiato sospeso per l'elezione al Senato di Scott Colom. Se i risultati confermassero la sua vittoria, Colom diventerebbe il primo senatore nero proveniente da questo stato del \"Deep South\" dai tempi della Ricostruzione successiva alla Guerra Civile Americana. Il voto rappresenta un momento storico per la comunità afroamericana locale, segnando un potenziale punto di svolta nella rappresentanza politica dopo oltre un secolo di esclusione dalle cariche senatoriali statali. Lo riferisce PBS NewsHour.",
   "more": [
    "Il periodo della Ricostruzione (1863-1877) vide una breve fase di diritti civili per gli ex schiavi nel Sud degli Stati Uniti, durante la quale vennero eletti i primi rappresentanti neri. Seguì però l'era delle leggi Jim Crow, che impose la segregazione e rimosse sistematicamente la rappresentanza politica afroamericana per decenni."
   ],
