   "sez": "ambiente",
   "titolo": "Filippine, il Negros First CyberCentre passa all'energia solare",
   "orig": "Negros First CyberCentre goes solar",
   "lead": "Il Negros First CyberCentre, a Bacolod City nelle Filippine, ha ufficialmente avviato la transizione verso l'energia pulita con l'installazione di 949 pannelli solari. Il progetto, realizzato in collaborazione con lo sviluppatore privato Wegen, è stato annunciato dal funzionario provinciale Rayfrando Diaz. Questa iniziativa segue l'esempio di un numero crescente di strutture nel Paese che cercano opzioni ecosostenibili per ridurre l'impatto ambientale e i costi energetici, segnando un importante traguardo negli sforzi del governo provinciale verso la sostenibilità e l'indipendenza energetica. Lo riferisce Philippine Daily Inquirer.",
   "more": [
    "Le Filippine stanno incentivando l'adozione di energie rinnovabili per affrontare la dipendenza dai combustibili fossili importati e la vulnerabilità del sistema elettrico nazionale ai disastri naturali. L'energia solare, in particolare, è favorita dall'elevata esposizione solare dell'arcipelago, contribuendo agli obiettivi globali di riduzione delle emissioni di gas serra."
   ],
