   "titolo": "Electra Aero EL9: il velivolo che promette di rivoluzionare i viaggi regionali",
   "orig": "Meet the Electra Aero EL9, an aircraft that might just revolutionise point-to-point travel",
   "lead": "La startup statunitense Electra Aero ha presentato l'EL9, un velivolo progettato per rivoluzionare i viaggi punto a punto attraverso il concetto aerodinamico delle ali soffiate ad alta portanza. L'aereo è pensato per operare su brevi tratte lontano dai grandi aeroporti convenzionali, permettendo decolli e atterraggi in spazi ridotti. L'obiettivo dell'azienda è trasformare il mercato dei trasporti regionali, offrendo una soluzione efficiente e flessibile per collegare centri urbani e aree periferiche, riducendo i tempi di percorrenza e l'impatto logistico dei piccoli spostamenti. Lo riferisce Wallpaper*.",
   "more": [
    "La tecnologia delle \"blown wings\" (ali soffiate) utilizza il flusso d'aria dei motori per aumentare la portanza a basse velocità, consentendo operazioni STOL (Short Take-Off and Landing). Questo tipo di ingegneria è considerato fondamentale per lo sviluppo della mobilità aerea regionale e urbana sostenibile del futuro."
   ],
