   "id": "z297483fc",
   "sez": "salute",
   "titolo": "Sierra Leone, attività di prevenzione per Mpox ed Ebola",
   "orig": "NPHA Engages High-Risk Groups in Western Area on Mpox Prevention and Ebola Preparedness",
   "lead": "L'Agenzia Nazionale per la Salute Pubblica della Sierra Leone, in collaborazione con il Ministero della Salute e l'Organizzazione Mondiale della Sanità, ha avviato un'attività di sensibilizzazione rivolta ai gruppi ad alto rischio nell'Area Occidentale. L'iniziativa si concentra sulla prevenzione del vaiolo delle scimmie (Mpox) e sulla preparazione alle emergenze legate al virus Ebola. Gli operatori sanitari mirano a informare le comunità sulle misure di sicurezza e sui protocolli di monitoraggio per prevenire la diffusione di epidemie e garantire una risposta rapida a eventuali focolai. Lo riferisce Sierraloaded.",
   "more": [
    "Il Mpox e l'Ebola sono malattie virali che hanno causato gravi emergenze sanitarie in Africa Occidentale. La sorveglianza epidemiologica e l'educazione delle comunità sono strumenti essenziali per contenere i focolai, specialmente in regioni dove le infrastrutture sanitarie possono trovarsi sotto forte pressione durante le crisi epidemiche."
   ],
