   "sez": "musica",
   "titolo": "Assisi, oltre 400 voci gospel per il festival diffuso della pace",
   "orig": "Dalle piazza di Assisi un inno di pace e gioia con oltre 400 voci gospel",
   "lead": "Ad Assisi ha preso il via il primo festival diffuso e itinerante di musica spiritual, portando nelle piazze della città umbra oltre 400 voci gospel. L'evento è stato concepito come un inno collettivo di pace e gioia, unendo coristi e musicisti in una manifestazione artistica che attraversa i luoghi simbolo della città. La rassegna mira a celebrare i valori della fratellanza e della spiritualità attraverso il linguaggio universale del canto corale, coinvolgendo residenti e turisti in un'atmosfera di festa e riflessione spirituale. Lo riferisce ANSA.",
   "more": [
    "La musica gospel ha radici nella tradizione spirituale afroamericana e si è diffusa globalmente come espressione di fede e speranza. Assisi, città di San Francesco, è tradizionalmente legata a messaggi di pace universale, rendendola un palcoscenico ideale per manifestazioni che promuovono l'armonia interculturale e religiosa."
   ],
