   "id": "ze9dc6922",
   "sez": "ambiente",
   "titolo": "L'Uzbekistan lavora alla bozza del nuovo Codice Ambientale",
   "orig": "Uzbekistan Refines Draft of New Environmental Code",
   "lead": "L'Uzbekistan sta perfezionando la bozza di un nuovo Codice Ambientale con l'obiettivo di consolidare le leggi vigenti in materia di natura e sostenibilità. Il documento mira a rafforzare la protezione dell'ambiente e a promuovere l'uso responsabile delle risorse naturali attraverso una normativa più chiara e organica. La revisione fa parte di un piano nazionale per modernizzare il quadro legislativo, garantendo una gestione più efficace degli ecosistemi e rispondendo alle sfide ecologiche attuali per assicurare uno sviluppo economico che rispetti i limiti ambientali del Paese. Lo riferisce UzDaily.",
   "more": [
    "L'Uzbekistan sta affrontando sfide ambientali significative, come la desertificazione e la gestione delle scarse risorse idriche nell'Asia Centrale. La creazione di un Codice Ambientale unitario è un tentativo di coordinare le diverse agenzie governative e stabilire standard più rigorosi per la tutela del territorio dalle emissioni industriali."
   ],
