   "sez": "cultura",
   "titolo": "India, ex giudice critica il cambio di rotta diplomatica verso Israele",
   "orig": "India’s policy shift towards Israel is regrettable, says former Madras High Court judge at book launch",
   "lead": "Durante la presentazione di un libro in India, un ex giudice dell'Alta Corte di Madras ha espresso rammarico per il recente cambio di rotta della politica estera nazionale nei confronti di Israele. Il volume presentato raccoglie articoli che analizzano le ostilità tra Stati Uniti e Iran e il conflitto tra Israele e Libano. Il magistrato ha criticato la posizione attuale del governo, definendola un allontanamento dalla tradizione diplomatica indiana, sollevando un dibattito sulle responsabilità sociali e internazionali del Paese nel contesto dei conflitti in Medio Oriente. Lo riferisce The Hindu.",
   "more": [
    "L'India ha storicamente mantenuto una posizione di non allineamento. Negli ultimi anni, tuttavia, i rapporti con Israele si sono intensificati significativamente nei settori della difesa e della tecnologia, portando a una partnership strategica che ha cambiato sensibilmente gli equilibri diplomatici di Nuova Delhi nella regione mediorientale."
   ],
