   "id": "zf84090d9",
   "sez": "dibattito",
   "titolo": "Torino, migliaia in corteo contro il riarmo e il carovita",
   "orig": "Torino, in migliaia in corteo contro riarmo e carovita: in testa un trattore",
   "lead": "Migliaia di manifestanti, tra cui studenti, agricoltori e docenti, hanno sfilato a Torino per protestare contro il carovita e le crescenti spese per il riarmo. La manifestazione, aperta da un trattore degli Agricoltori Autonomi Italiani, ha attraversato il centro cittadino chiedendo interventi immediati per sostenere il potere d'acquisto delle famiglie. Il dibattito si concentra sulla scelta di allocare risorse pubbliche nel settore della difesa: i manifestanti chiedono di spostare i fondi verso la scuola e il welfare per contrastare l'inflazione, denunciando una gestione delle risorse non rispondente ai bisogni sociali. Lo riferisce Il Fatto Quotidiano.",
   "more": [
    "Il dibattito sulla spesa militare in Italia si è intensificato dopo le richieste della NATO di aumentare il budget per la difesa. Mentre i sostenitori del riarmo lo ritengono necessario per la sicurezza nazionale, i movimenti di protesta sostengono che in una fase di crisi le priorità dovrebbero essere la sanità e l'istruzione."
   ],
