   "sez": "tech",
   "titolo": "Oppo Find X10: i nuovi smartphone puntano sulla naturalezza fotografica",
   "orig": "I nuovi smartphone Oppo Find X10 restituiscono verità alle foto",
   "lead": "A Palma di Maiorca è stata presentata la nuova serie di smartphone Oppo Find X10, che punta a rivoluzionare la fotografia mobile cercando di restituire fedeltà e verità alle immagini. L'azienda intende superare il paradosso delle foto tecnicamente perfette ma eccessivamente artificiali, tipiche dei recenti sviluppi tecnologici, puntando su un'elaborazione dell'immagine più naturale. La sfida lanciata da Oppo riguarda il bilanciamento tra l'intelligenza artificiale e la realtà visiva, cercando di offrire dispositivi capaci di catturare scatti che rispettino l'estetica autentica della scena reale. Lo riferisce Il Messaggero – Tecnologia.",
   "more": [
    "L'industria degli smartphone ha integrato algoritmi di intelligenza artificiale sempre più complessi per migliorare automaticamente le foto. Tuttavia, questo può portare a una perdita di naturalezza; la nuova tendenza è quindi quella di affinare i sensori per ritrovare una resa fotografica più vicina a quella delle fotocamere professionali."
   ],
