   "id": "z37efb00d",
   "sez": "mondo",
   "titolo": "Il premier australiano Albanese celebra la comunità nepalese a Sydney",
   "orig": "Australian PM Albanese dons Dhaka topi to celebrate Nepal Festival in Sydney",
   "lead": "Il Primo Ministro australiano Anthony Albanese ha partecipato per la prima volta al Nepal Festival di Sydney, indossando il tradizionale cappello \"Dhaka topi\" in segno di rispetto. Durante l'evento svoltosi al Darling Harbour, che ha radunato migliaia di persone, Albanese ha lodato il contributo fondamentale della comunità nepalese alla società e alla cultura dell'Australia. La partecipazione del capo del governo sottolinea l'importanza del multiculturalismo nel Paese e il riconoscimento dei legami sociali ed economici sempre più stretti tra la nazione australiana e la numerosa diaspora nepalese. Lo riferisce The Kathmandu Post.",
   "more": [
    "Il Nepal Festival è un evento annuale che celebra la cultura e le tradizioni nepalesi all'estero. In Australia, la comunità nepalese è una delle popolazioni immigrate in più rapida crescita, contribuendo significativamente alla diversità culturale e alla forza lavoro, specialmente nei settori dell'istruzione superiore e dei servizi sanitari."
   ],
