   "id": "z1e8ee61d",
   "sez": "tech",
   "titolo": "Presentato il progetto dell'E9X, aereo elettrico da novanta posti",
   "orig": "E9X, cos'è l'aereo ?sovrappeso? a batteria che trasporta fino a 90 passeggeri con un'autonomia di 1.000 chilometri",
   "lead": "Il settore dell'aviazione sperimenta nuove soluzioni per ridurre l'impatto ambientale con il progetto dell'E9X, un velivolo passeggeri alimentato a batteria capace di trasportare fino a novanta persone con un'autonomia stimata di circa mille chilometri. La struttura dell'aeromobile si distingue per ali ripiegabili di oltre cinquanta metri di apertura, sei motori elettrici e quaranta pacchi batterie del peso complessivo di una tonnellata ciascuno. Daniel Jacobson ha definito il mezzo una struttura volutamente sovrappeso proprio a causa della notevole stazza delle unità energetiche necessarie a garantire la spinta. Lo riferisce Il Messaggero – Tecnologia.",
   "more": [
    "L'elettrificazione del trasporto aereo rappresenta una delle sfide ingegneristiche più complesse nella transizione ecologica. La densità energetica delle batterie attuali è infatti di gran lunga inferiore a quella del cherosene tradizionale, costringendo i progettisti a bilanciare la capacità di carico con il peso imponente degli accumulatori su rotte regionali a corto raggio."
   ],
