   "sez": "economia",
   "titolo": "La Corea del Sud avvia l'esportazione di cachi in Cina dopo diciassette anni",
   "orig": "Lee hails Korea’s first persimmon export to China in 17 years",
   "lead": "Il presidente sudcoreano Lee Jae-myung ha annunciato l'inizio della prima spedizione di cachi verso il mercato cinese, traguardo raggiunto al termine di diciassette anni di complesse trattative commerciali tra i due Paesi. Intervenendo sul social network X, il capo dello Stato ha assicurato il sostegno del governo per aprire nuovi sbocchi commerciali esteri a favore dell'agricoltura nazionale. Lee ha sottolineato come l'espansione oltre il Sud-est asiatico rappresenti una preziosa opportunità di diversificazione per le comunità rurali locali, contribuendo a rafforzare la competitività complessiva del comparto agroalimentare. Lo riferisce The Korea Herald.",
   "more": [
    "L'accesso di prodotti ortofrutticoli freschi su mercati esteri richiede spesso lunghi negoziati su protocolli fitosanitari e standard doganali. Per i coltivatori sudcoreani l'apertura della Cina, mercato confinante con un'elevata domanda di prodotti ortofrutticoli di qualità, offre un importante canale di sbocco commerciale contro le fluttuazioni dei prezzi interni."
   ],
