   "titolo": "Premier League, l'Arsenal supera l'Hull City con una rete di Ødegaard",
   "orig": "Premier League: Ο Όντεγκααρντ «λύγισε» Χαλ και Τζολάκη, ντεμπούτο για Μουζακίτη",
   "lead": "L'Arsenal ha superato l'ostacolo dell'Hull City imponendosi per una rete a zero in un combattuto match di Premier League. La resistenza difensiva dell'Hull, guidata dal portiere greco Konstantis Tzolakis, ha retto per settantadue minuti prima di capitolare di fronte al capitano dei campioni d'Inghilterra Martin Ødegaard. Il gol decisivo è nato da un tiro di Madueke respinto da Tzolakis, sul quale il centrocampista norvegese si è avventato per primo ribadendo il pallone in rete. La sfida ha visto anche il debutto in campo del giovane greco Mouzakitis. Lo riferisce ERT News.",
   "more": [
    "Le partite di Premier League contro squadre ben organizzate difensivamente richiedono spesso pazienza e cinismo sotto porta alle formazioni di vertice. Il ruolo dei portieri risulta determinante nel prolungare la parità, ma le seconde palle in area di rigore restano l'arma principale per scardinare i blocchi difensivi compatti."
   ],
