   "sez": "economia",
   "titolo": "La tenuta del rublo russo tra spese militari e deficit di bilancio",
   "orig": "Russia, rublo tra le monete più forti del mondo (nonostante la crisi): ecco perché e cosa può succedere nel 2027",
   "lead": "Il rublo russo mostra segnali di notevole resistenza sui mercati valutari internazionali nonostante l'impatto crescente della guerra in Ucraina sui conti pubblici di Mosca. Il prolungarsi delle ostilità belliche sta aggravando la spesa statale, con un deficit di bilancio che rischia di rivelarsi quasi doppio rispetto alle stime inizialmente formulate dalle autorità economiche. Parallelamente, il regime delle sanzioni internazionali continua a sottrarre risorse cruciali alle entrate pubbliche, aprendo interrogativi sulle prospettive di stabilità e sulle possibili evoluzioni monetarie previste per il 2027. Lo riferisce Il Messaggero – Economia.",
   "more": [
    "La resilienza della valuta russa è stata sostenuta da controlli sui capitali, tassi di interesse elevati e proventi delle esportazioni energetiche reindirizzate verso l'Asia. Tuttavia, l'aumento della spesa per la difesa e il disavanzo pubblico generano forti pressioni inflazionistiche sulla struttura economica interna."
   ],
