   "orig": "La economía de Ucrania se contrae ante agravamiento de los efectos de los ataques rusos",
   "lead": "L'attività economica in Ucraina registra una fase di sensibile contrazione a causa delle pesanti conseguenze provocate dal moltiplicarsi degli attacchi e dei bombardamenti russi sulle infrastrutture del Paese. Le valutazioni formulate dalla banca centrale ucraina delineano un quadro di forte incertezza, prevedendo tuttavia una modesta ripresa del prodotto interno lordo pari allo 0,4 per cento per il 2027. Tale dinamica di recupero resta strettamente vincolata alla possibilità di sbloccare i porti marittimi e di consentire la piena ripresa delle esportazioni commerciali nazionali. Lo riferisce El Tiempo.",
   "more": [
    "Il conflitto armato ha colpito pesantemente la rete energetica, la logistica dei trasporti e i centri industriali ucraini, riducendo drasticamente la capacità produttiva. Le esportazioni agricole e minerarie via mare rappresentano la principale fonte di valuta estera per sostenere il bilancio dello Stato."
   ],
