   "titolo": "São Tomé, bloccato conto della Banca centrale per un risarcimento a Synergies",
   "orig": "Conta do Banco Central atingida por execução relacionada com indemnização à Synergies",
   "lead": "Le autorità giudiziarie hanno disposto il blocco di uno dei conti correnti della Banca centrale di São Tomé e Príncipe nell'ambito di una procedura esecutiva avviata in Portogallo per un indennizzo di 5,5 milioni di euro. La decisione scaturisce da una storica controversia legale che vede contrapposto lo Stato insulare alla società Synergies. Il ministro dell'Economia e delle Finanze ha chiarito che l'istituto di emissione ha già provveduto a nominare un collegio di avvocati per intraprendere tutte le necessarie azioni di difesa legale. Lo riferisce Téla Nón.",
   "more": [
    "I contenziosi commerciali internazionali possono portare all'esecuzione forzata di beni o conti statali all'estero qualora vengano riconosciuti i lodi arbitrali. Per piccole economie insulari, il blocco di risorse liquide della banca centrale rischia di creare temporanee tensioni nella gestione dei pagamenti internazionali."
   ],
