   "id": "zb2ba04a8",
   "sez": "mondo",
   "titolo": "Mélenchon riunisce ventimila militanti al Bourget e lancia la sfida per il 2027",
   "orig": "Avec une nouvelle démonstration de force de Jean-Luc Mélenchon, les insoumis s'y voient déjà",
   "lead": "Jean-Luc Mélenchon ha tenuto una grande manifestazione politica al Parco delle esposizioni di Le Bourget, riunendo circa ventimila sostenitori per presentare il programma presidenziale di La France Insoumise in vista delle elezioni del 2027. Il quattro volte candidato ha rivendicato con fermezza la propria linea radicale, rifiutando compromessi moderati e affermando di proporre come unica scelta ragionevole quella di cambiare tutto per aprire una nuova fase politica nel Paese. I militanti presenti hanno accolto il leader con cori di vittoria, manifestando ottimismo sulle possibilità di affermazione elettorale del movimento.",
   "more": [
    "La Francia Insoumise si posiziona come forza cardine della sinistra transalpina, puntando su una rottura decisa con le politiche liberoscambiste e sulle riforme costituzionali per una nuova Repubblica. IlBourget ha ospitato storicamente i grandi raduni della sinistra francese nei passaggi cruciali delle campagne presidenziali."
   ],
