   "id": "z60421d37",
   "sez": "mondo",
   "titolo": "La prima chiesa cattolica dell'Oman festeggia il giubileo d'oro",
   "orig": "Golden Jubilee opens at Oman’s first Catholic church",
   "lead": "La chiesa dei Santi Pietro e Paolo a Mascate, primo luogo di culto cattolico edificato nel sultanato dell'Oman, ha aperto le celebrazioni ufficiali per il suo cinquantesimo anniversario dalla consacrazione. In occasione dell'apertura del giubileo d'oro, il vescovo Paolo Martinelli, vicario apostolico dell'Arabia meridionale, ha rivolto un messaggio alla comunità dei fedeli invitando i cattolici ad approfondire la propria fede e a testimoniarla con generosità. L'evento rappresenta una ricorrenza significativa per la presenza cristiana nella penisola arabica e per la convivenza interreligiosa nella regione. Lo riferisce Vatican News.",
   "more": [
    "Le comunità cattoliche nei Paesi della penisola arabica sono composte in prevalenza da lavoratori immigrati, soprattutto filippini e indiani. La libertà di culto regolata e la cooperazione con i governi locali permettono la vita delle parrocchie storiche come quella di Mascate nel quadro del vicariato apostolico."
   ],
