   "orig": "Egypt reopens embassy in Libya's Tripoli after 12-year closure",
   "lead": "L'Egitto ha riaperto sabato la propria ambasciata a Tripoli, in Libia, segnando un riavvicinamento ufficiale con l'amministrazione occidentale del Paese dopo dodici anni di chiusura. La notizia è stata confermata dal ministero degli Affari Esteri del Cairo, indicando una normalizzazione dei rapporti diplomatici nell'area.",
