   "orig": "Lucknow-bound IndiGo flight returns to Bengaluru after hijack threat note found onboard",
   "lead": "Il volo IndiGo 6E-451, decollato da Bangalore e diretto a Lucknow, è stato costretto a rientrare all'aeroporto di partenza dopo il ritrovamento di un biglietto che minacciava il dirottamento del velivolo. L'allarme ha scatenato il panico a bordo circa trenta minuti dopo il decollo.",
