   "lead": "Mathieu Lefèvre è stato nominato portavoce temporaneo del governo francese, sostituendo Maud Bregeon in congedo maternità per cinque settimane. Lefèvre manterrà contemporaneamente il suo incarico di ministro delegato alla Transizione ecologica. In parallelo, Arnaud Viala è stato nominato nuovo ministro della Ruralità.",
