   "titolo": "Guerra e stravolgimenti climatici aggravano la malnutrizione infantile in Sudan",
   "orig": "Sudan war and climate change see parents struggle to feed their children",
   "lead": "In Sudan la combinazione tra il conflitto armato in corso, la povertà diffusa e gli effetti dei cambiamenti climatici sta rendendo sempre più difficile per i genitori garantire il nutrimento quotidiano ai propri figli. Le autorità sanitarie e le organizzazioni di soccorso segnalano un consistente aumento dei casi di malnutrizione infantile sul territorio nazionale. Le difficoltà di approvvigionamento alimentare e la distruzione delle infrastrutture agricole aggravano una crisi umanitaria drammatica che colpisce milioni di famiglie sudanesi. Lo riferisce Al Jazeera.",
