   "titolo": "Un astronauta pakistano prenderà parte alla prossima missione spaziale cinese",
   "orig": "Pakistani astronaut to join China’s next space station mission",
   "lead": "Un astronauta di nazionalità pakistana prenderà parte alla prossima missione spaziale della Cina denominata Shenzhou-24 a bordo dell'avamposto orbitale cinese. Si tratta del primo cittadino straniero a viaggiare sulla stazione spaziale della Cina, nell'ambito di un accordo di cooperazione scientifica e tecnologica tra i due paesi. L'identità dello specialista di missione non è stata ancora resa nota dalle autorità competenti fino al completamento delle fasi finali di addestramento previste prima del lancio. Lo riferisce Al Jazeera.",
