   "sez": "prima",
   "titolo": "Iniziative per il miglioramento delle competenze lavorative e sportive in Lettonia e all'estero",
   "orig": "Workers offered chance to improve Latvian language skills",
   "lead": "L'Agenzia statale per l'impiego della Lettonia ha avviato un programma che offre ai lavoratori l'opportunità di acquisire o perfezionare gratuitamente la conoscenza della lingua lettone. L'iniziativa rientra nei progetti di formazione continua del Fondo Sociale Europeo Plus e punta a rafforzare la competitività dei dipendenti e favorire l'inclusione lavorativa. In ambito internazionale emergono parallele iniziative di potenziamento delle competenze giovanili nello sport, con piani di addestramento in Europa previsti per i tennisti di Hong Kong e del Bhutan.",
   "more": [
    "La formazione continua dei lavoratori rappresenta uno strumento chiave promosso dalle istituzioni europee per adeguare le competenze linguistiche e professionali alle esigenze del mercato del lavoro globale. I fondi comunitari sostengono progetti diretti all'integrazione sociale e all'aumento dell'occupabilità in diversi settori produttivi."
   ],
