   "lead": "Il cantautore australiano Nick Cave ha annunciato una nuova serie di date in Nord America per il 2027 intitolata \"Conversations With Nick Cave: An Evening of Talk & Music\". Il formato dello spettacolo prevede un'interazione diretta con il pubblico presente in sala attraverso sessioni di domande e risposte aperte, alternate a esibizioni musicali dal vivo da solista al pianoforte. L'artista proporrà un'esperienza informale destinata ad approfondire il legame artistico e personale con i propri fan.",
