   "lead": "Le autorità dello Stato di Western Bahr el Ghazal, nel Sudan del Sud, hanno disposto la chiusura degli uffici di due compagnie aeree commerciali nella città di Wau. Il provvedimento è stato adottato in seguito al rifiuto dei vettori Kush Airlines e Arojet Airlines di riscuotere la tassa di bollo di 5 dollari imposta sul biglietto di ogni passeggero. I rappresentanti governativi hanno ribadito l'obbligatorietà del contributo amministrativo per l'utilizzo delle infrastrutture aeroportuali locali.",
