   "orig": "How Nuclear Technology Is Helping Cities Become More Sustainable",
   "lead": "L'Agenzia internazionale per l'energia atomica ha diffuso un rapporto speciale dedicato al contributo delle tecnologie nucleari nello sviluppo di città sostenibili. Lo studio illustra come l'applicazione di tecniche isotopiche e strumenti radiologici possa aiutare i centri urbani a monitorare la qualità dell'aria, gestire le risorse idriche sotterranee e ottimizzare il trattamento dei rifiuti in modo ecologico. Lo riferisce l'Agenzia internazionale per l'energia atomica (Aiea).",
