   "titolo": "Batterie per smartphone sostituibili dagli utenti dal 2027 secondo le norme europee",
   "orig": "Tutela dei minori: la sicurezza dei nostri figli deve essere una priorità assoluta",
   "lead": "A partire dal 2027, le nuove normative stabilite dall'Unione Europea imporranno che le batterie degli smartphone e di altri dispositivi elettronici possano essere sostituite direttamente dagli utenti. Questa misura segnerà la fine dell'obbligo di rivolgersi a tecnici specializzati o a centri di assistenza autorizzati per effettuare il cambio della batteria consumata. Il provvedimento mira a modificare in modo significativo la gestione dei dispositivi tecnologici, estendendo la loro durata e semplificando le riparazioni per i consumatori europei.",
   "more": [
    "La normativa sulle batterie rientra nelle direttive dell'Unione Europea volte a promuovere il diritto alla riparazione e l'economia circolare. Negli ultimi anni, la diffusione di dispositivi con componenti sigillati ha reso complesse e costose le riparazioni fai-da-te. L'introduzione di batterie facilmente sostituibili mira a prolungare il ciclo di vita dei prodotti elettronici e a ridurre la produzione di rifiuti tecnologici."
   ],
