   "sez": "italia",
   "titolo": "Apertura di KFC nei rifugi di montagna e polemiche sulla tutela delle osterie tradizionali",
   "orig": "Da Cortina a Campiglio, il pollo fritto di Kfc sulle piste da sci. È polemica: “Salvate i rifugi”",
   "lead": "L'apertura dei ristoranti di pollo fritto della catena KFC sulle piste da sci tra Cortina e Campiglio ha scatenato accese polemiche sul futuro della montagna italiana. Il fondatore di Eataly chiede leggi specifiche a tutela delle osterie tradizionali e dell'identità gastronomica dei rifugi alpini. Parallelamente, la società alpinistica sottolinea come la presenza nei rifugi di centri benessere e piscine rappresenti un problema di gestione idrica in aree dove la risorsa dell'acqua scarseggia. Lo riferisce la Repubblica.",
   "more": [
    "La gestione dei rifugi di alta quota è al centro del dibattito tra la difesa delle tradizioni culinarie locali e la spinta verso la commercializzazione turistica. La scarsità di risorse idriche nelle zone montane pone inoltre rilevanti questioni di sostenibilità ambientale ed energetica."
   ],
