   "sez": "musica",
   "titolo": "I Placebo in concerto a Milano per il tour del trentesimo anniversario",
   "orig": "I Placebo a Milano sono stati nostalgia futurista",
   "lead": "La band britannica dei Placebo si è esibita a Milano nell'ambito del loro tour celebrativo per il trentesimo anniversario. Il concerto si è caratterizzato per una proposta musicale definita di nostalgia futurista, con brani storici ampiamente rivisitati. Durante la serata non sono mancati i malumori dei componenti del gruppo legati all'uso dei telefoni cellulari da parte degli spettatori tra il pubblico. Lo riferisce Rolling Stone Italia.",
   "more": [
    "I Placebo, nati negli anni Noveanta a Londra, sono uno dei gruppi di riferimento dell'alt-rock europeo. Nel corso dei loro concerti, la band ha spesso espresso contrarietà nei confronti del pubblico che registra video con i telefoni invece di seguire lo spettacolo."
   ],
