   "id": "z77b7fba3",
   "sez": "salute",
   "titolo": "Il consumo giornaliero di caffè associato a una riduzione del rischio di demenza",
   "orig": "Drinking 2–3 cups of coffee a day linked to dramatically lower dementia risk",
   "lead": "Uno studio durato 43 anni ha rilevato che il consumo quotidiano di due o tre tazzine di caffè con caffeina è associato a una riduzione significativa del rischio di sviluppare forme di demenza e a una migliore funzionalità cognitiva. I benefici riscontrati dai ricercatori prescindono dalla predisposizione genetica dei soggetti analizzati, mentre la versione decaffeinata della bevanda non ha mostrato le medesime correlazioni positive nello studio. Lo riferisce ScienceDaily – Medicina.",
   "more": [
    "La demenza comprende diverse patologie neurodegenerative che compromettono la memoria e le capacità cognitive. Negli ultimi anni la ricerca scientifica ha approfondito gli effetti dei nutrienti e dello stile di vita, analizzando in particolare l'azione protettiva dei composti bioattivi presenti nel caffè."
   ],
