   "id": "zaacbf76f",
   "sez": "adolescenti",
   "titolo": "Marracash inaugura un nuovo campo sportivo nella sua ex scuola media a Milano",
   "orig": "Marracash torna nella sua ex scuola media e inaugura il nuovo campo sportivo: “Spero di aver restituito almeno un po’ di tutto ciò che ho ricevuto”",
   "lead": "Venerdì 6 novembre il rapper Marracash è tornato nella sua ex scuola media di Milano per inaugurare un campo sportivo nuovo di zecca destinato agli studenti. L'impianto è stato realizzato grazie ai fondi raccolti dall'artista lo scorso aprile durante l'evento musicale Marra Block Party. Durante il taglio del nastro tra gli applausi dei bambini, il cantante ha espresso la soddisfazione di aver restituito alla propria comunità giovanile parte di quanto ricevuto. Lo riferisce Orizzonte Scuola.",
   "more": [
    "Le iniziative di beneficenza promosse dagli artisti musicali nelle periferie urbane mirano a riqualificare i contesti scolastici e sociali d'origine. L'ammodernamento di impianti sportivi all'interno delle scuole favorisce l'integrazione, l'attività fisica e l'aggregazione giovanile nei quartieri popolari."
   ],
