   "sez": "salute",
   "titolo": "In Zambia appello del deputato Kelvin Kunda per lo screening oncologico precoce",
   "orig": "Law marker calls for cancer screening",
   "lead": "In Zambia il parlamentare della circoscrizione di Lima, Kelvin Kunda, ha lanciato un accorato appello ai cittadini per sollecitare l'esecuzione di controlli regolari di screening oncologico. Il deputato ha avvertito che la diagnosi tardiva costituisce una delle cause principali del valore elevato dei decessi legati al cancro nel Paese, esortando la popolazione a svolgere visite preventive prima dell'insorgenza di sintomi evidenti. Lo riferisce Lusaka Times.",
   "more": [
    "Gli screening oncologici di massa rappresentano uno strumento di prevenzione fondamentale nei sistemi sanitari. La diagnosi precoce dei tumori consente di intervenire tempestivamente con terapie meno invasive, migliorando la sopravvivenza dei pazienti e riducendo la pressione sugli ospedali."
   ],
