   "id": "z15eb7fe0",
   "sez": "prima",
   "titolo": "L'Uzbekistan propone di ospitare un ufficio regionale dell'ONU contro il terrorismo",
   "orig": "Uzbekistan Offers to Host Regional UN Counterterrorism Office at Astana Summit",
   "lead": "Durante il vertice dell'Iniziativa di Aqaba tenutosi ad Astana, in Kazakistan, il presidente dell'Uzbekistan Shavkat Mirziyoyev ha proposto la creazione nel proprio Paese di un ufficio regionale dell'Ufficio delle Nazioni Unite contro il terrorismo. All'incontro hanno preso parte i leader dell'Asia centrale, alti funzionari dell'Azerbaigian e del Kirghizistan, e il re Abdullah II di Giordania. La proposta mira ad affrontare le crescenti minacce alla sicurezza legate all'uso dell'intelligenza artificiale e delle tecnologie digitali da parte dei gruppi terroristici.",
   "more": [
    "Il Processo di Aqaba è un'iniziativa lanciata dalla Giordania per rafforzare la cooperazione militare e d'intelligence internazionale nella lotta al terrorismo globale. L'integrazione di tecnologie avanzate come l'intelligenza artificiale da parte di organizzazioni estremiste ha reso prioritaria la risposta coordinata tra le nazioni dell'Asia centrale e della regione mediorientale."
   ],
