   "id": "ze6a85024",
   "sez": "mondo",
   "titolo": "Russia: Putin accoglie con favore la telefonata dei leader di Finlandia e Norvegia",
   "orig": "Source tells Vlast newsletter that Putin welcomed late-October call from Finland’s president and Norway’s prime minister as a possible start of substantive talks with Europe",
   "lead": "Il presidente russo Vladimir Putin ha accolto con favore la telefonata ricevuta a fine ottobre dal presidente finlandese Alexander Stubb e dal primo ministro norvegese Jonas Gahr Støre, considerandola come un possibile segnale d'avvio per negoziati di merito con i Paesi europei. A riferire l'apertura del Cremlino è stata la giornalista Farida Rustamova all'interno della newsletter informativa Vlast, citando fonti vicine alla presidenza russa che interpretano il colloquio come un potenziale canale di dialogo politico diretto con l'Europa.",
   "more": [
    "Le relazioni diplomatiche tra la Russia e i Paesi nordici hanno subito un forte irrigidimento negli ultimi anni, segnato dall'adesione della Finlandia alla NATO e dal rafforzamento della cooperazione di difesa della Norvegia. Eventuali contatti diretti tra i vertici di governo rappresentano segnali d'attenzione nel complesso panorama della sicurezza continentale."
   ],
