   "titolo": "Kosovo: identificate altre tre persone scomparse durante la guerra del 1999",
   "orig": "Kosovo Identifies Three More Wartime Missing Persons",
   "lead": "Tre intellettuali albanesi del Kosovo, che erano stati fatti sparire con la forza dalle forze di sicurezza serbe nell'aprile del 1999, sono stati ufficialmente identificati all'interno di una fossa comune situata nel nord del Kosovo. La certezza sulle loro identità è giunta a distanza di anni grazie agli esami sulle salme rinvenute, consentendo di fare luce su alcuni dei casi di sparizione forzata risalenti al periodo del conflitto armato nella regione balcanica.",
