   "sez": "mondo",
   "titolo": "Sudan: un blackout di quattro giorni paralizza gli ospedali nello Stato del Nilo Bianco",
   "orig": "Four-day blackout disrupts hospital services, livelihoods in Sudan’s White Nile state",
   "lead": "Un'interruzione prolungata della corrente elettrica durata quattro giorni ha paralizzato le attività sanitarie negli ospedali e i servizi essenziali nella città di El Dueim, nello Stato del Nilo Bianco in Sudan. Parallelamente, nello Stato del Nilo Azzurro, l'attacco condotto da un drone ha causato un guasto alla rete di alimentazione provocando la chiusura forzata del centro di dialisi della capitale locale. Entrambi gli eventi stanno mettendo a dura prova la sopravvivenza dei pazienti affetti da patologie croniche.",
   "more": [
    "Il conflitto civile in Sudan ha provocato il collasso sistemico delle infrastrutture energetiche e sanitarie in numerose regioni del Paese. Le interruzioni di corrente prolungate compromettono il funzionamento dei macchinari salvavita negli ospedali, la conservazione dei farmaci e l'accesso all'acqua potabile per la popolazione civile."
   ],
