   "id": "z05e5212d",
   "sez": "mondo",
   "titolo": "Sud Sudan: un tribunale condanna un pastore e un capo tradizionale per violazione delle norme sui funerali",
   "orig": "Yambio court jails pastor, sub-chief over funeral regulation violations",
   "lead": "Un tribunale di Yambio, nello Stato dell'Equatoria Occidentale in Sud Sudan, ha condannato a una pena detentiva un pastore religioso e un sub-capo tradizionale per aver violato i regolamenti locali stabiliti per le cerimonie funebri. La sentenza punisce il mancato rispetto delle disposizioni comunitarie volte a contingentare gli assembramenti e a mantenere l'ordine pubblico durante le celebrazioni commemorative, segnando un'applicazione rigida delle ordinanze locali sul territorio della contea. Lo riferisce Radio Tamazuj.",
   "more": [
    "Nelle aree rurali del Sud Sudan le autorità giudiarie locali applicano sia il diritto statale sia le normative consuetudinarie stabilite dalle leadership comunitarie. Il rispetto delle regole sugli eventi pubblici e sui funerali viene monitorato per prevenire disordini sociali e garantire l'osservanza delle disposizioni amministrative regionali."
   ],
