   "id": "z42200abd",
   "sez": "mondo",
   "titolo": "Tagikistan: si celebra il 32° anniversario dell'adozione della Costituzione",
   "orig": "Tajikistan marks 32nd anniversary of Constitution",
   "lead": "Il Tagikistan ha celebrato il trentaduesimo anniversario dell'adozione della propria Carta Costituzionale, la legge fondamentale approvata mediante un referendum popolare il 6 novembre 1994. Il testo costituzionale ha definito le fondamenta giuridiche del Paese emerso dall'indipendenza post-sovietica, proclamando il Tagikistan uno Stato sovrano, democratico, laico e unitario. La ricorrenza rappresenta una festività nazionale che commemora la garanzia formale dei diritti civili e delle libertà fondamentali nel Paese centralasiatico.",
   "more": [
    "La Costituzione del Tagikistan del 1994 fu adottata in una fase complessa della storia del Paese, segnata dalla guerra civile successiva all'indipendenza. L'approvazione della Carta ha rappresentato un passaggio chiave per la stabilizzazione delle istituzioni statali e l'organizzazione dell'ordinamento giuridico nazionale."
   ],
