   "sez": "economia",
   "titolo": "Senegal: revocato il blocco sulle importazioni di patate",
   "orig": "Commerce : levée du gel des importations de pommes de terre",
   "lead": "Il Ministero dell'Industria e del Commercio del Senegal ha annunciato la revoca del blocco sulle importazioni di patate con una circolare ufficiale. La misura autorizza nuovamente l'ingresso del tubero sul mercato nazionale dopo il periodo di sospensione temporanea. Allo stesso tempo, nell'isola di Maurizio, i coltivatori locali esprimono forte preoccupazione per possibili perdite fino al 40% dei raccolti di patate causate dall'infestazione della mosca minatrice delle foglie.",
   "more": [
    "I provvedimenti di sospensione e riapertura delle importazioni di beni alimentari vengono impiegati dai governi per regolare l'offerta interna, proteggere i prezzi per i consumatori e tutelare la produzione agricola locale durante i periodi di raccolto. Le infestazioni da parassiti rappresentano invece un rischio costante per la sicurezza alimentare."
   ],
